'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import type { LucideIcon } from 'lucide-react'

import {
  Sidebar,
  SidebarProvider,
  SidebarHeader,
  SidebarContent,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
  SidebarInset,
  SidebarTrigger,
  useSidebar,
} from '@/components/ui/sidebar'

export interface AdminShellNavItem {
  href:  string
  label: string
  icon:  LucideIcon
}

export interface AdminShellNavSection {
  label: string
  items: AdminShellNavItem[]
}

export interface AdminShellProps {
  defaultOpen:    boolean
  sections:       AdminShellNavSection[]
  children:       React.ReactNode
  /** Hauteur de la navbar globale au-dessus de la sidebar. Défaut : 3.5rem (h-14). */
  navbarHeight?:  string
  /** Libellé du header sidebar. Défaut : "Administration". */
  headerLabel?:   string
}

function estActif(pathname: string | null, href: string): boolean {
  if (!pathname) return false
  return pathname === href || pathname.startsWith(href + '/')
}

function MobileTrigger() {
  const { isMobile, openMobile } = useSidebar()
  if (!isMobile || openMobile) return null
  return (
    <div className="fixed left-3 top-17 z-30 md:hidden">
      <SidebarTrigger className="bg-white shadow-sm border" />
    </div>
  )
}

export function AdminShell({
  defaultOpen,
  sections,
  children,
  navbarHeight = '3.5rem',
  headerLabel  = 'Administration',
}: AdminShellProps) {
  const pathname = usePathname()

  if (sections.length === 0) {
    return <>{children}</>
  }

  const sidebarOffset = { top: navbarHeight, height: `calc(100svh - ${navbarHeight})` }

  return (
    <SidebarProvider defaultOpen={defaultOpen}>
      <Sidebar collapsible="icon" style={sidebarOffset}>
        <SidebarHeader>
          <div className="flex items-center justify-between gap-2 group-data-[collapsible=icon]:justify-center">
            <span className="px-2 py-1.5 text-xs font-semibold uppercase tracking-wide text-muted-foreground group-data-[collapsible=icon]:hidden">
              {headerLabel}
            </span>
            <SidebarTrigger />
          </div>
        </SidebarHeader>
        <SidebarContent>
          {sections.map(section => (
            <SidebarGroup key={section.label}>
              <SidebarGroupLabel>{section.label}</SidebarGroupLabel>
              <SidebarGroupContent>
                <SidebarMenu>
                  {section.items.map(item => {
                    const Icon   = item.icon
                    const active = estActif(pathname, item.href)
                    return (
                      <SidebarMenuItem key={item.href}>
                        <SidebarMenuButton asChild isActive={active} tooltip={item.label}>
                          <Link href={item.href}>
                            <Icon className="size-4" />
                            <span>{item.label}</span>
                          </Link>
                        </SidebarMenuButton>
                      </SidebarMenuItem>
                    )
                  })}
                </SidebarMenu>
              </SidebarGroupContent>
            </SidebarGroup>
          ))}
        </SidebarContent>
      </Sidebar>
      <SidebarInset>
        <MobileTrigger />
        {children}
      </SidebarInset>
    </SidebarProvider>
  )
}
